  // Initialize nodes
  for (const word of words) {
    if (word.length === l1 || word.length === l2) {
      graph[word] = [];
    }
  }

  // Add edges
  for (const word1 of Object.keys(graph)) {
    for (const word2 of Object.keys(graph)) {
      if (word1 !== word2 && canTransform(word1, word2)) {
        graph[word1].push(word2);
      }
    }
  }

  return graph;
