  if (visited === null) {
    visited = new Set();
  }

  // Don't allow paths to the same word
  if (start === end && visited.size === 0) {
    return false;
  }

  if (start === end && visited.size > 0) {
    return true;
  }

  visited.add(start);
  for (const nbr of graph[start]) {
    if (!visited.has(nbr)) {
      if (hasPath(graph, nbr, end, visited)) {
        return true;
      }
    }
  }
  return false;
